import SwiftUI

// Generated by stitch-native (state mode) from a Stitch export. Do not hand-edit; regenerate.
// Stateless view: all data comes in through `state`, all actions go out through callbacks.

struct OrdersListViewState: Equatable {
    struct Line: Equatable {
        let quantity: Int
        let name: String
    }

    enum OrderStatus: String, CaseIterable {
        case recebida
        case preparar
        case noForno
        case pronta

        var title: LocalizedStringKey {
            switch self {
            case .recebida: "ordersList.status.recebida"
            case .preparar: "ordersList.status.preparar"
            case .noForno: "ordersList.status.noForno"
            case .pronta: "ordersList.status.pronta"
            }
        }
    }

    struct Order: Identifiable, Equatable {
        let id: UUID
        let number: String
        let date: String
        let price: Int  // cents
        let title: String
        let paoAlentejano: String
    }

    var orders: [Order]
    var preparacao: String
    var tempoEstimado: String
    var encomenda: String
    var status: OrderStatus
    var date: String
    var lojaAlcobaca: String
    var date2: String
    var date3: String
    var lines: [Line]
    var price: Int  // cents
    var registos: String
    var brandName: String
    var levantamento: String
    var lerAlc: String
}

