                    .buttonStyle(.plain)
                    .accessibilityAddTraits(.isSelected)
                    Button { /* # */ } label: {
                        VStack(alignment: .center, spacing: 0) {
                            Image(systemName: "questionmark.square.dashed")  // material: account_balance_wallet
                            Text("ordersList.carteira")
                                .font(.system(.caption2, weight: .medium))
                                .foregroundStyle(StitchTheme.onSurfaceVariant)
                                .padding(.top, 2)  // margin
                            VStack(alignment: .leading, spacing: 0) {
                            }
                            .frame(maxWidth: .infinity, alignment: .leading)
                            .frame(width: 4, height: 4)
                            .background(StitchTheme.secondary, in: Capsule())
                            .padding(.top, 2)  // margin
                        }
                        .padding(.leading, 4)
                        .padding(.trailing, 4)
                    }
                    .buttonStyle(.plain)
                    Button { /* # */ } label: {
                        VStack(alignment: .center, spacing: 0) {
                            Image(systemName: "questionmark.square.dashed")  // material: person_outline
                            Text("ordersList.perfil")
                                .font(.system(.caption2, weight: .medium))
                                .foregroundStyle(StitchTheme.onSurfaceVariant)
                                .padding(.top, 2)  // margin
                            VStack(alignment: .leading, spacing: 0) {
                            }
                            .frame(maxWidth: .infinity, alignment: .leading)
                            .frame(width: 4, height: 4)
                            .background(StitchTheme.secondary, in: Capsule())
                            .padding(.top, 2)  // margin
                        }
                        .padding(.leading, 4)
                        .padding(.trailing, 4)
                    }
                    .buttonStyle(.plain)
                }
                .frame(maxWidth: .infinity, alignment: .leading)
                .padding(.leading, 8)
                .padding(.trailing, 8)
                .frame(height: 64)
                .background(StitchTheme.surfaceContainerLowest.opacity(0.9), in: Capsule())
            }
            .padding(.leading, 20)
            .padding(.trailing, 20)
            .padding(.bottom, 12)  // margin
        }
    }

    private func money(_ cents: Int) -> String {
        (Decimal(cents) / 100).formatted(.currency(code: "EUR").locale(Locale(identifier: "pt")))
    }
}

private extension OrdersListView {
    enum Tab: String, CaseIterable, Identifiable {
        case active, past

        var id: Self { self }

        var title: LocalizedStringKey {
            switch self {
            case .active: "ordersList.tab.active"
            case .past: "ordersList.tab.past"
            }
        }
    }
}

